from openpyxl import load_workbook
from openpyxl.styles import Alignment, Font
import re

def process_sheet(wb, sheet_name='Sheet1'):
    wb = load_workbook('input.xlsx')
    sheet = wb[sheet_name]

    # Ensure Excel is set to Automatic Calculation
    # This is a workaround since openpyxl doesn't directly set calculation mode
    # We assume the workbook is already set to Automatic Calculation

    # Convert any text-stored formulas back to formulas
    for row in sheet.iter_rows():
        for cell in row:
            if cell.data_type == 'f' and cell.value is None:
                cell.value = cell.formula
                cell.data_type = 'f'

    # Set calculation mode to Automatic (this is a workaround)
    # Note: openpyxl does not support setting calculation mode directly

    # Round numbers in columns D, E, F to one decimal place
    for row in sheet.iter_rows(min_col=4, max_col=6):
        for cell in row:
            if cell.data_type == 'n':
                cell.value = round(cell.value, 1)

    # Apply number formatting to columns D, E, F
    for cell in sheet['D'] + sheet['E'] + sheet['F']:
        if cell.data_type == 'n':
            cell.number_format = '0.0'

    # Identify blocks of data separated by blank rows
    blocks = []
    current_block = []
    for row in sheet.iter_rows(min_row=1, max_row=sheet.max_row):
        if row[0].value is None:  # Blank row
            if current_block:
                blocks.append(current_block)
                current_block = []
        else:
            current_block.append(row)
    if current_block:
        blocks.append(current_block)

    # Sort each block by column D in descending order
    for block in blocks:
        # Extract rows and sort
        rows = block
        sorted_rows = sorted(rows, key=lambda r: r[3].value, reverse=True)

        # Clear the original block
        for row in block:
            for cell in row:
                cell.value = None

        # Write the sorted rows back
        for i, row in enumerate(sorted_rows):
            for j, cell in enumerate(row):
                sheet.cell(row=i + block[0][0].row, column=j + 1, value=cell.value)

    # Ensure one blank row between blocks
    block_start_rows = [block[0][0].row for block in blocks]
    for i in range(1, len(block_start_rows)):
        # Insert a blank row between blocks
        sheet.insert_rows(block_start_rows[i] + 1)

    # Reapply formatting to columns D, E, F
    for row in sheet.iter_rows(min_col=4, max_col=6):
        for cell in row:
            if cell.data_type == 'n':
                cell.number_format = '0.0'
                cell.font = Font(bold=True)
                cell.alignment = Alignment(horizontal='center')

    # Save the workbook
    wb.save('output.xlsx')

process_sheet(None)
