from openpyxl import load_workbook
from openpyxl.utils import range_boundaries

def delete_empty_rows_based_on_id(wb, sheet_name, id_col, data_start, data_end, i2_cell):
    sheet = wb[sheet_name]
    # Get the ID from cell I2
    target_id = i2_cell.value
    # Find all ranges where the ID appears in column B
    ranges = []
    current_range = None
    for row in sheet.iter_rows(min_col=2, max_col=2, min_row=1, max_row=sheet.max_row):
        if row[0].value == target_id:
            if current_range is None:
                current_range = (row[0].row, row[0].row)
            else:
                current_range = (current_range[0], row[0].row)
        else:
            if current_range is not None:
                ranges.append(current_range)
                current_range = None
    if current_range is not None:
        ranges.append(current_range)

    # Delete empty rows within each range
    for start_row, end_row in ranges:
        for row in range(end_row, start_row - 1, -1):
            is_empty = True
            for col in range(1, 10):  # Check all columns for non-empty cells
                if sheet.cell(row=row, column=col).value is not None:
                    is_empty = False
                    break
            if is_empty:
                sheet.delete_rows(row)

    # Remove the last empty row if it exists
    if sheet.max_row > 0:
        last_row = sheet.max_row
        if sheet.cell(row=last_row, column=1).value is None:
            sheet.delete_rows(last_row)

def delete_all_empty_rows(wb, sheet_name):
    sheet = wb[sheet_name]
    # Delete empty rows
    for row in range(sheet.max_row, 0, -1):
        is_empty = True
        for col in range(1, 10):  # Check all columns for non-empty cells
            if sheet.cell(row=row, column=col).value is not None:
                is_empty = False
                break
        if is_empty:
            sheet.delete_rows(row)
    # Remove the last empty row if it exists
    if sheet.max_row > 0:
        last_row = sheet.max_row
        if sheet.cell(row=last_row, column=1).value is None:
            sheet.delete_rows(last_row)

def main():
    wb = load_workbook('input.xlsx')
    sheet_name = 'DATA'
    i2_cell = wb[sheet_name]['I2']

    # Delete empty rows based on ID if I2 is not empty
    if i2_cell.value:
        delete_empty_rows_based_on_id(wb, sheet_name, 'B', 'A1', 'E19', i2_cell)
    else:
        delete_all_empty_rows(wb, sheet_name)

    # Save the result
    wb.save('output.xlsx')

if __name__ == "__main__":
    main()
