from openpyxl import load_workbook

# Load the workbook and select the active sheet
wb = load_workbook('input.xlsx')
ws = wb.active

# Extract the scores from rows 5 to 7 (B to E)
scores = []
for row in ws.iter_rows(min_row=5, max_row=7, min_col=2, max_col=5):
    scores.append([cell.value for cell in row])

# Flatten the scores into a single list of tuples (person, score)
# We'll use the row number (5, 6, 7) as the person identifier
flat_scores = []
for i, row in enumerate(scores, start=5):
    for score in row:
        flat_scores.append((i, score))

# Group the scores by person and sum them
from collections import defaultdict
person_scores = defaultdict(int)
for person, score in flat_scores:
    person_scores[person] += score

# Get the highest score
max_score = max(person_scores.values())

# Determine which people have the highest score
top_people = [person for person, score in person_scores.items() if score == max_score]

# Assign points based on the number of people with the highest score
if len(top_people) == 1:
    points = {person: 6 for person in top_people}
elif len(top_people) == 2:
    points = {person: 3 for person in top_people}
elif len(top_people) == 3:
    points = {person: 2 for person in top_people}
else:
    points = {person: 0 for person in person_scores}

# Write the computed points into the range B5:E7
for row_idx, row in enumerate(scores, start=5):
    for col_idx, cell in enumerate(row, start=1):
        person = row_idx
        if person in points:
            ws.cell(row=row_idx, column=col_idx + 1, value=points[person])

# Save the workbook
wb.save('output.xlsx')
