wb = load_workbook('input.xlsx')
ws = wb.active

# Create a dictionary to store the highest non-US invoice amount for each customer
customer_max_non_us = {}

# Iterate through the rows to compute the required values
for row in ws.iter_rows(min_row=2, max_col=4, max_row=27):
    customer = row[0].value
    total = row[1].value
    country = row[2].value

    # If the country is not 'US', store the total in the dictionary for the customer
    if country != 'US':
        if customer not in customer_max_non_us:
            customer_max_non_us[customer] = total
        else:
            if total > customer_max_non_us[customer]:
                customer_max_non_us[customer] = total

# Write the computed values into column D
for row in ws.iter_rows(min_row=2, min_col=4, max_row=27):
    customer = row[0].value
    country = row[2].value

    if country != 'US':
        row[3].value = country
    else:
        row[3].value = customer_max_non_us.get(customer, '')

# Save the workbook
wb.save('output.xlsx')
